//! Proof: the engine's HTML pages mounted in one Shadow DOM per page.
//!
//! The page fragment is generated by `soma-render-html` from the same
//! `PagedLayout` the PDF backend consumes. The overlay is a sibling layer
//! inside the same shadow root; it reads line boxes from the layout, never
//! from DOM measurements.

use leptos::html;
use leptos::prelude::*;
use wasm_bindgen::prelude::*;
use wasm_bindgen::JsCast;
use web_sys::{MouseEvent, ShadowRoot, ShadowRootInit, ShadowRootMode};

use crate::state::{use_studio, Studio};

const SHADOW_CSS: &str = r#"
:host{all:initial;color:#111;color-scheme:light}
.page{margin:0!important;box-shadow:none!important;background:transparent!important;color:#111!important;color-scheme:light;pointer-events:none;}
svg.page{display:block;width:100%;height:100%;}
svg text{font-family:var(--soma-serif,serif);}
svg text[data-family="sans"]{font-family:var(--soma-sans,sans-serif)!important;}
svg text[data-family="serif"]{font-family:var(--soma-serif,serif)!important;}
svg text[data-family="mono"]{font-family:var(--soma-mono,monospace)!important;}
svg text[data-math]{font-family:var(--soma-math,serif)!important;}
svg g.block[data-family="sans"]{font-family:var(--soma-sans,sans-serif)!important;color:#111;}
svg g.block[data-family="serif"]{font-family:var(--soma-serif,serif)!important;color:#111;}
svg g.block[data-family="mono"]{font-family:var(--soma-mono,monospace)!important;color:#111;}
.page .math{font-family:var(--soma-math,serif);}
.page [style*="font-family:sans-serif"]{font-family:var(--soma-sans,sans-serif)!important;}
.page [style*="font-family:serif"]{font-family:var(--soma-serif,serif)!important;}
.page [style*="font-family:monospace"]{font-family:var(--soma-mono,monospace)!important;}
.page .math{font-family:var(--soma-math,serif)!important;}
.ov{position:absolute;left:0;top:0;width:100%;height:100%;overflow:hidden;}
.ov-margin{position:absolute;border:1px dashed var(--margin-guide);pointer-events:none;}
.ov-line{position:absolute;border:1px solid transparent;border-left-color:var(--overlay-line);pointer-events:auto;border-radius:1px;}
.ov-line:hover{background:var(--accent-soft);border-color:var(--overlay-strong);}
.ov-line.selected{background:var(--accent-soft);border-color:var(--overlay-strong);box-shadow:0 0 0 1px var(--overlay-strong) inset;}
.ov-line.overfull{border-color:var(--flag-overfull);border-style:dashed;}
.ov-line.emergency{border-color:var(--flag-emergency);border-style:dotted;}
.ov-trim{position:absolute;background:var(--trim-zone);border-top:1px solid var(--trim-line);border-bottom:1px solid var(--trim-line);pointer-events:none;}
.ov-cl{position:absolute;font:700 9px/1.2 var(--mono,monospace);color:var(--amber);background:var(--amber-soft);border:1px solid var(--amber);border-radius:3px;padding:0 3px;pointer-events:none;}
.ov-flag{position:absolute;width:3px;border-radius:2px;pointer-events:none;}
.ov-flag.overfull{background:var(--flag-overfull);}
.ov-flag.emergency{background:var(--flag-emergency);}
"#;

#[component]
pub fn ProofPane() -> impl IntoView {
    let studio = use_studio();
    let viewport = NodeRef::<html::Div>::new();
    let tick = RwSignal::new(0u32);
    let ran = StoredValue::new(false);

    // Recompute "fit" when the window or the surrounding panels change.
    Effect::new(move |_| {
        let _ = tick.get();
        studio.build.with(|_| ());
        let _ = studio.fit.get();
        let _ = studio.sidebar_width.get();
        let _ = studio.sidebar_open.get();
        let _ = studio.ai_width.get();
        let _ = studio.ai_open.get();
        if !studio.fit.get_untracked() {
            return;
        }
        let Some(viewport) = viewport.get() else {
            return;
        };
        let width = viewport.client_width() as f64;
        if width <= 0.0 {
            return;
        }
        if let Some((base_width, _, _)) = geometry(&studio) {
            let zoom = ((width - 48.0) / base_width).clamp(0.25, 3.0);
            studio.zoom.set(zoom);
        }
    });

    // A first fit after the browser has laid out the shell.
    Effect::new(move |_| {
        if ran.get_value() {
            return;
        }
        ran.set_value(true);
        leptos::task::spawn_local(async move {
            gloo_timers::future::TimeoutFuture::new(40).await;
            tick.update(|value| *value += 1);
        });
    });

    // Window resize listener; one per pane.
    Effect::new(move |_| {
        let Some(window) = web_sys::window() else {
            return;
        };
        let closure = Closure::<dyn FnMut()>::new(move || {
            tick.update(|value| *value += 1);
        });
        let _ = window.add_event_listener_with_callback("resize", closure.as_ref().unchecked_ref());
        closure.forget();
    });

    let pages = Memo::new(move |_| {
        studio.build.with(|build| {
            build
                .as_ref()
                .map(|build| (0..build.svg_fragments.len()).collect::<Vec<_>>())
                .unwrap_or_default()
        })
    });

    view! {
        <div class="proof-scroll" node_ref=viewport>
            <div class="proof-pages">
                {move || {
                    if studio.build.with(|build| build.is_none()) {
                        if let Some(error) = studio.build_error.get() {
                            view! {
                                <div class="empty-state">
                                    <div class="mark">"!"</div>
                                    <strong>"构建失败"</strong>
                                    <span class="mono" style="max-width:640px;white-space:pre-wrap">{error}</span>
                                </div>
                            }.into_any()
                        } else {
                            view! {
                                <div class="empty-state">
                                    <div class="mark">"S"</div>
                                    <strong>"正在排版"</strong>
                                    <span>"浏览器内的引擎正在解析、断行与分页。"</span>
                                </div>
                            }.into_any()
                        }
                    } else {
                        view! {
                            {move || studio.build_error.get().map(|error| view! {
                                <div class="banner bad" id="build-diagnostic" style="margin:12px 0;max-width:760px">
                                    <span class="fill">{format!("服务端构建失败；校样保留上一版。{error}")}</span>
                                </div>
                            })}
                            <For
                                each={move || pages.get()}
                                key={|index| *index}
                                children={move |index| view! { <PageSlot index=index/> }}
                            />
                        }.into_any()
                    }
                }}
            </div>
        </div>
    }
}

#[component]
fn PageSlot(index: usize) -> impl IntoView {
    let studio = use_studio();
    let style = move || {
        let zoom = studio.zoom.get();
        match geometry(&studio) {
            Some((width, height, _)) => {
                format!("width:{:.2}px;height:{:.2}px", width * zoom, height * zoom)
            }
            None => String::from("width:0;height:0"),
        }
    };
    view! {
        <div class="page-slot" data-page={index + 1} style=style>
            <Page index=index/>
        </div>
    }
}

#[component]
fn Page(index: usize) -> impl IntoView {
    let studio = use_studio();
    let host = NodeRef::<html::Div>::new();

    // Page content + overlay. Re-runs when the build, overlay flag or the
    // effective zoom changes (zoom changes the host font size, not the HTML).
    Effect::new(move |_| {
        let Some(element) = host.get() else {
            return;
        };
        let Some((_, _, px_per_em)) = geometry(&studio) else {
            return;
        };
        let zoom = studio.zoom.get();
        let _ = studio.overlay.get();
        let _ = web_sys::HtmlElement::style(&element)
            .set_property("font-size", &format!("{:.4}px", px_per_em * zoom));
        let Some(html) = studio.build.with(|build| {
            build.as_ref().and_then(|build| {
                let fragment = build.svg_fragments.get(index)?;
                let page = build.build.pages.pages.get(index)?;
                Some(page_svg_html(
                    &fragment.body,
                    page,
                    &build.build.pages,
                    studio.overlay.get_untracked(),
                ))
            })
        }) else {
            return;
        };
        let shadow = shadow_root(&element);
        shadow.set_inner_html(&html);
        install_click_listener(&element, studio, index);
    });

    // Selection highlight without rebuilding the page.
    Effect::new(move |_| {
        let Some(element) = host.get() else {
            return;
        };
        let selection = studio.selection.get();
        let Some(shadow) = element.shadow_root() else {
            return;
        };
        let Ok(nodes) = shadow.query_selector_all(".ov-line.selected") else {
            return;
        };
        for index in 0..nodes.length() {
            if let Some(node) = nodes.item(index) {
                if let Some(element) = node.dyn_ref::<web_sys::Element>() {
                    let _ = element.class_list().remove_1("selected");
                }
            }
        }
        if selection.page != index || selection.block == usize::MAX {
            return;
        }
        let selector = format!(
            "[data-b=\"{}\"][data-l=\"{}\"]",
            selection.block, selection.line
        );
        if let Ok(Some(element)) = shadow.query_selector(&selector) {
            let _ = element.class_list().add_1("selected");
        }
    });

    view! { <div class="page-host" node_ref=host></div> }
}

fn shadow_root(element: &web_sys::HtmlElement) -> ShadowRoot {
    element.shadow_root().unwrap_or_else(|| {
        element
            .attach_shadow(&ShadowRootInit::new(ShadowRootMode::Open))
            .expect("attach shadow root")
    })
}

fn install_click_listener(element: &web_sys::HtmlElement, studio: Studio, page: usize) {
    if element.get_attribute("data-listener").is_some() {
        return;
    }
    let _ = element.set_attribute("data-listener", "1");
    let closure = Closure::<dyn FnMut(MouseEvent)>::new(move |event: MouseEvent| {
        let path = event.composed_path();
        for index in 0..path.length() {
            let value = path.get(index);
            if value.is_undefined() || value.is_null() {
                continue;
            }
            let Ok(node) = value.dyn_into::<web_sys::Element>() else {
                continue;
            };
            if !node.class_list().contains("ov-line") {
                continue;
            }
            let block = node
                .get_attribute("data-b")
                .and_then(|value| value.parse::<usize>().ok());
            let line = node
                .get_attribute("data-l")
                .and_then(|value| value.parse::<usize>().ok());
            let node_id = node
                .get_attribute("data-node")
                .and_then(|value| value.parse::<i64>().ok())
                .unwrap_or(-1);
            if let (Some(block), Some(line)) = (block, line) {
                studio.selection.set(crate::state::Selection {
                    page,
                    block,
                    line,
                    node: node_id,
                });
                studio.page.set(page);
                studio.mode.set(crate::state::Mode::Inspect);
                event.stop_propagation();
            }
            break;
        }
    });
    let _ = element.add_event_listener_with_callback("click", closure.as_ref().unchecked_ref());
    closure.forget();
}

fn geometry(studio: &Studio) -> Option<(f64, f64, f64)> {
    studio.build.with(|build| {
        let build = build.as_ref()?;
        let page = &build.build.pages.page;
        let body = build.build.styled.body_pt();
        let px_per_em = body.num() as f64 / body.den() as f64 * 96.0 / 72.0;
        let width = page.width.0 as f64 / 4096.0 * px_per_em;
        let height = page.height.0 as f64 / 4096.0 * px_per_em;
        Some((width, height, px_per_em))
    })
}

fn page_svg_html(
    body: &str,
    page: &soma_layout::Page,
    layout: &soma_layout::PagedLayout,
    overlay: bool,
) -> String {
    let mut html = String::with_capacity(body.len() + 4096);
    html.push_str("<style>");
    html.push_str(SHADOW_CSS);
    html.push_str("</style>");
    html.push_str(body);
    if overlay {
        html.push_str(&overlay_html(page, layout));
    }
    html
}

fn overlay_html(page: &soma_layout::Page, layout: &soma_layout::PagedLayout) -> String {
    let mut html = String::from("<div class=\"ov\">");
    let content_width = layout.page.content_width().0;
    let content_height = layout.page.content_height().0;
    html.push_str(&format!(
        "<div class=\"ov-margin\" style=\"left:{};top:{};width:{};height:{};\"></div>",
        em(layout.page.margin_left.0),
        em(layout.page.margin_top.0),
        em(content_width),
        em(content_height)
    ));

    let footnote_top = (content_height - page.footnote_height.0).max(0);
    for (block_index, block) in page.blocks.iter().enumerate() {
        append_block_overlay(&mut html, layout, block, block_index, 0);
    }
    let footnote_offset = page.blocks.len();
    for (block_index, block) in page.footnotes.iter().enumerate() {
        append_block_overlay(
            &mut html,
            layout,
            block,
            footnote_offset + block_index,
            footnote_top,
        );
    }
    html.push_str("</div>");
    html
}

fn append_block_overlay(
    html: &mut String,
    layout: &soma_layout::PagedLayout,
    block: &soma_layout::PlacedBlock,
    block_index: usize,
    extra_y: i32,
) {
    for (line_index, placed) in block.lines.iter().enumerate() {
        let line = &placed.line;
        let left = layout.page.margin_left.0 + block.x.0 + line.indent.0;
        let top = layout.page.margin_top.0 + block.y.0 + extra_y + placed.y.0;
        let mut class = String::from("ov-line");
        if line.overfull {
            class.push_str(" overfull");
        }
        if line.emergency {
            class.push_str(" emergency");
        }
        html.push_str(&format!(
            "<div class=\"{}\" data-b=\"{}\" data-l=\"{}\" data-node=\"{}\" style=\"left:{};top:{};width:{};height:{};\" title=\"ratio {}‰ · cost {}\"></div>",
            class,
            block_index,
            line_index,
            block.node.0,
            em(left),
            em(top),
            em(line.target_width.0),
            em(line.height.0),
            line.ratio_milli,
            line.cost.0
        ));
        if line.trim_left.0 > 0 {
            html.push_str(&format!(
                "<div class=\"ov-trim\" style=\"left:{};top:{};width:{};height:{};\"></div>",
                em(left - line.trim_left.0),
                em(top),
                em(line.trim_left.0),
                em(line.height.0)
            ));
        }
        if line.trim_right.0 > 0 {
            html.push_str(&format!(
                "<div class=\"ov-trim\" style=\"left:{};top:{};width:{};height:{};\"></div>",
                em(left + line.target_width.0 - line.trim_right.0),
                em(top),
                em(line.trim_right.0),
                em(line.height.0)
            ));
        }
        if !line.cjk_latin_adjustments.is_empty() {
            let title = line
                .cjk_latin_adjustments
                .iter()
                .map(|adjust| format!("{}:{}", adjust.boundary, adjust.adjustment))
                .collect::<Vec<_>>()
                .join(" ");
            html.push_str(&format!(
                "<span class=\"ov-cl\" style=\"left:{};top:{};\" title=\"{}\">CL {}</span>",
                em(left),
                em(top - 1900),
                title,
                line.cjk_latin_adjustments.len()
            ));
        }
        if line.overfull || line.emergency {
            let flag = if line.overfull {
                "overfull"
            } else {
                "emergency"
            };
            html.push_str(&format!(
                "<span class=\"ov-flag {}\" style=\"left:{};top:{};height:{};\"></span>",
                flag,
                em(left + line.target_width.0 + 200),
                em(top),
                em(line.height.0)
            ));
        }
    }
}

fn em(units: i32) -> String {
    let sign = if units < 0 { "-" } else { "" };
    let absolute = units.unsigned_abs();
    format!(
        "{}{}.{:03}em",
        sign,
        absolute / 4096,
        (absolute % 4096) * 1000 / 4096
    )
}
